141	/// The root for a single workspace: the connection gate until its tailnet
142	/// first reaches `Running`, then the dashboard for the rest of the session.
143	/// Observes the workspace's `StatusViewModel` directly so the `running` flip
144	/// is tracked live.
145	private struct WorkspaceRoot: View {
146	    let workspace: Workspace
147	    @StateObject private var tabManager: TabManager
148	    @StateObject private var statusViewModel: StatusViewModel
149	    @Binding var showingSettings: Bool
150	
151	    /// Flips to true the first time this workspace's tailnet reaches `Running`
152	    /// and stays true — so a transient reconnect doesn't kick back to the gate.
153	    @State private var hasConnected = false
154	
155	    init(workspace: Workspace, showingSettings: Binding<Bool>) {
156	        self.workspace = workspace
157	        // Resolve the workspace-owned session lazily here (first render), NOT
158	        // in `Workspace.init` before the window exists. This preserves the
159	        // gesture-recognizer crash fix from upstream.
160	        _tabManager = StateObject(wrappedValue: workspace.tabManager)
161	        _statusViewModel = StateObject(wrappedValue: workspace.statusViewModel)
162	        self._showingSettings = showingSettings
163	    }
164	
165	    var body: some View {
166	        Group {
167	            if hasConnected, let tab = tabManager.currentTab {
168	                DashboardContent(
169	                    workspace: workspace,
170	                    homePage: workspace.homePage,
171	                    model: workspace.model,
172	                    tab: tab,
173	                    statusViewModel: statusViewModel,
174	                    session: workspace.session,
175	                    onSettings: { showingSettings = true }
176	                )
177	            } else {
178	                ConnectionGateView(
179	                    statusViewModel: statusViewModel,
180	                    onSettings: { showingSettings = true }
181	                )
182	            }
183	        }
184	        .onAppear {
185	            if statusViewModel.running { hasConnected = true }
186	            ensureFreshTab()
187	        }
188	        .onChange(of: statusViewModel.running) { _, running in
189	            if running { hasConnected = true }
190	            ensureFreshTab()
191	        }
192	        .onDisappear {
193	            tabManager.unloadAllWebViews()
194	        }
195	    }
